    v22 = g.math('MULTIPLY', v2, v21)
    v23 = g.math('ADD', v17, v22)
    v24 = g.math('ADD', v23, 0.0001)
    v25 = g.math('MULTIPLY', v12, v12)
    v26 = g.math('DIVIDE', v8, v25)
    v27 = g.math('DIVIDE', 0.5, v24)
    v28 = g.math('MULTIPLY', v26, v27)
