    v20 = g.vmath('MULTIPLY', v14, v19)
    v21 = g.vmath('SCALE', (4327800000, 9304600000, 6612100000), s=-1.0)
    v22 = g.bc(v5)
    v23 = g.vmath('MULTIPLY', v21, v22)
    v24 = g.bc(v5)
    v25 = g.vmath('MULTIPLY', v23, v24)
