    v27 = g.bc(v26)
    v28 = g.vmath('MULTIPLY', v20, v27)
    v29 = g.math('MULTIPLY', 2, v2)
    v30 = g.math('MULTIPLY', v29, 4528200000)
    v31 = g.math('SQRT', v30, 0.0)
    v32 = g.math('MULTIPLY', 9.747E-14, v31)
    v33 = g.math('MULTIPLY', 2239900, v5)
    v34 = g.sep(v1)
